const setHITLSessionScan = `-- name: SetHITLSessionScan :exec
UPDATE hitl_sessions
SET task_cursor = $1, updated_at = now(), failures = 0, next_scan_at = NULL,
    scanned_at = CASE WHEN $2::boolean THEN now() ELSE scanned_at END
WHERE kagent_session_id = $3
`

type SetHITLSessionScanParams struct {
	Cursor          *string
	Done            bool
	KagentSessionID string
}

// A scan that is not done keeps its old scanned_at, so the session is picked again at once. A page
// that was read clears the session's failure backoff.
func (q *Queries) SetHITLSessionScan(ctx context.Context, arg SetHITLSessionScanParams) error {
	_, err := q.db.Exec(ctx, setHITLSessionScan, arg.Cursor, arg.Done, arg.KagentSessionID)
	return err
}

const supersedeLiveHITLForTask = `-- name: SupersedeLiveHITLForTask :many
UPDATE hitl_requests
SET availability = 'unavailable', unavailable_reason = 'A newer request replaced this one',
    updated_at = now()
WHERE kagent_session_id = $1 AND task_id = $2 AND id <> $3 AND availability IN ('pending', 'stale')
RETURNING id
`

type SupersedeLiveHITLForTaskParams struct {
	KagentSessionID string
	TaskID          string
	ID              string
}

func (q *Queries) SupersedeLiveHITLForTask(ctx context.Context, arg SupersedeLiveHITLForTaskParams) ([]string, error) {
	rows, err := q.db.Query(ctx, supersedeLiveHITLForTask, arg.KagentSessionID, arg.TaskID, arg.ID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

